"""Canonical terminology and publication checks for GAKUMAS TH."""
import re

GLOSSARY={"体力":"พลังงาน","元気":"Genki (元気)","集中":"集中 (สมาธิ)","好調":"好調 (ฟอร์มดี)","絶好調":"絶好調 (ฟอร์มยอดเยี่ยม)","やる気":"やる気 (แรงจูงใจ)","好印象":"好印象 (ความประทับใจ)","温存":"温存 (เก็บแรง)","強気":"強気 (รุกหนัก)","全力":"全力 (ทุ่มสุดกำลัง)","全力値":"全力値","熱意":"熱意","指針":"指針","スキルカード":"การ์ดสกิล","アクティブ":"ประเภท Active","手札":"การ์ดในมือ","山札":"กองจั่ว","捨て札":"กองทิ้ง","保留":"ช่องพัก","レッスン":"Lesson","プロデュース":"Produce","上限解放":"ปลดขีดจำกัด","解放レベル":"ระดับปลดล็อก","恒常":"ถาวร","配布":"แจกจากอีเวนต์","完凸":"ปลดขีดจำกัดสูงสุด"}
CHARACTERS={"花海咲季":("Saki Hanami","ซากิ ฮานามิ"),"月村手毬":("Temari Tsukimura","เทมาริ สึกิมูระ"),"藤田ことね":("Kotone Fujita","โคโตเนะ ฟูจิตะ"),"有村麻央":("Mao Arimura","มาโอะ อาริมูระ"),"葛城リーリヤ":("Lilja Katsuragi","ลิลยา คัตสึรางิ"),"倉本千奈":("China Kuramoto","จินะ คุราโมโตะ"),"紫雲清夏":("Sumika Shiun","สุมิกะ ชิอุน"),"篠澤広":("Hiro Shinosawa","ฮิโระ ชิโนซาวะ"),"姫崎莉波":("Rinami Himesaki","รินามิ ฮิเมซากิ"),"花海佑芽":("Ume Hanami","อุเมะ ฮานามิ"),"十王星南":("Sena Juo","เซนะ จูโอ"),"秦谷美鈴":("Misuzu Hataya","มิสึสึ ฮาตายะ"),"雨夜燕":("Tsubame Amaya","สึบาเมะ อามายะ")}
FORBIDDEN=[(r'<br\s*/?>','literal br'),(r'รูปภาพของ|ภาพเรต|ภาพ SSR','image alt text'),(r'ลองเสี่ยงโชคกับซิมูเลเตอร์กาชา|กระตุ้นการโพสต์รีวิว','Game8 CTA'),(r'ไพ่|บัตรสกิล|การ์ดทักษะ','wrong card term'),(r'พลังชีวิต|ความแข็งแกร่งทางกายภาพ','wrong 体力 term'),(r'การยื่นออกมา|ระดับการเผยแพร่|ค่าเต็มที่','machine-translated mechanic'),(r'พลังงงาน+|โน้ตทิ้ง|P จุด','corrupt translation'),(r'[ก-๙](?:に|を|が|の|か)|(?:に|を|が|の|か)[ก-๙]','mixed Japanese particle'),(r'＋|％|（|）','full-width punctuation'),(r'(?<=[ก-๙A-Za-z0-9])、|、(?=[ก-๙A-Za-z0-9])','Japanese comma in prose'),(r'PLv\d|\dเทิร์น','missing spacing')]
def lint_text(text):return [label for pattern,label in FORBIDDEN if re.search(pattern,text or '',re.I)]
